import json, pathlib, html
p=pathlib.Path(__file__).resolve().parent; v=p/'versions'
families=[
('Launch Sheet','Editorial broadsheet','A confident newspaper grid makes the ownership promise and next action immediate.','Dense rules can compete with small text.','#f4f0e7','#171816','#ec5138','Arial, sans-serif'),
('Studio Desk','Tactile workbench','Physical layers make building feel approachable.','Decorative depth can distract from the action.','#ebe4d9','#33271f','#df7043','Georgia, serif'),
('Command Monument','Terminal architecture','A monumental command communicates developer control.','Terminal styling can deter non-developers.','#111513','#e5f0e3','#b4f95b','monospace'),
('Prism','Translucent layers','Overlapping planes suggest one idea expressed across screens.','Translucency needs careful contrast.','#e8edff','#202743','#7558ef','Arial, sans-serif'),
('Blueprint','Technical drawing','A diagram turns the app foundation into an inspectable object.','Engineering language can feel exclusive.','#173e63','#f1f7ff','#ffda68','monospace'),
('Operating Manual','Numbered instructions','Sequential steps explain how to get started.','A sequential treatment has less visual surprise.','#f8f6ee','#202b31','#e56d30','Georgia, serif'),
('The Conveyor','Production sequence','A linear path explains how an idea reaches multiple platforms.','A long sequence needs a compact mobile treatment.','#f0ebdf','#27231d','#fc6f43','Arial, sans-serif'),
('Orbital System','Platform constellation','A central idea and satellites communicate range.','The diagram is more metaphor than product interface.','#111b34','#edf4ff','#9adaff','Arial, sans-serif'),
('App Gallery','Outcome showcase','Device-shaped examples emphasize what people can make.','Illustrative examples should not be mistaken for real products.','#f5efeb','#29201e','#e05a40','Georgia, serif'),
('Type Sculpture','Oversized typography','The words themselves become an unmistakable graphic.','Large display type competes for space with the CTA.','#f1f34b','#181917','#f25335','Arial Black, sans-serif'),
('Receipt','Cost ledger','A ledger puts pricing and ownership in plain sight.','A receipt aesthetic can feel utilitarian.','#f4f0e2','#262820','#d05d3a','monospace'),
('Switchboard','Control panel','A tactile panel makes platform choice feel concrete.','Controls must not imply unsupported configuration.','#ddd9cf','#1e2524','#eb7149','Arial, sans-serif'),
('Open Frame','Exposed construction','An outlined scaffold makes ownership and openness tangible.','Construction marks can read as unfinished.','#faf9f5','#1b1c1d','#ff6246','Arial, sans-serif'),
('Stack of Cards','Layered artifacts','Separate platform cards make a broad offer easy to scan.','Cards are familiar and require careful art direction.','#ebe6fa','#25203b','#714ae3','Arial, sans-serif'),
('Kinetic Marquee','Graphic signage','Bold directional bands create energy without imagery.','Large text can overwhelm explanatory content.','#fc513a','#221915','#fff6e5','Arial Black, sans-serif'),
('Split Reality','Input and result','Side-by-side input and output show the workflow at a glance.','The output must remain visibly illustrative.','#f1f3f1','#142b25','#cfed66','Arial, sans-serif'),
('Index of Possibilities','Catalog system','A numbered platform index gives breadth structure.','The catalog is information-forward and quieter.','#e9e4d8','#262824','#bd4b38','Georgia, serif'),
('Workshop Window','Layered software windows','Familiar windows communicate local development.','A generic editor mockup can look like other tools.','#161b23','#edf0f3','#f4a968','monospace'),
('Signal Field','Network of points','A visual network ties a single idea to many targets.','Abstract connections need explicit labels.','#253dcb','#f8f9ff','#e2ff68','Arial, sans-serif'),
('Manifesto','Declarative statements','The ownership promise becomes the central visual identity.','Strong claims need supporting details nearby.','#f6f1e7','#1c1d19','#f05a37','Georgia, serif')]
variants=[('Front Page','Lead with a huge claim and a clear action.'),('Split Desk','Put the promise and the platform graphic side by side.'),('Platform First','Place the platform graphic before the claim.'),('Command Stage','Make the command the central object.'),('Editorial Rail','Use a narrow utility rail beside the main story.')]
headlines=['Completely free.<br>Your AI. Your computer. Your code.','Your idea.<br>Every screen.','Build here.<br>Go everywhere.','Your AI. Your computer.<br>Your code.','One idea.<br>Many places.']
# Different families alter their visual grammar, in addition to palette and type.
shapes=['sheet','desk','terminal','prism','blueprint','manual','conveyor','orbit','devices','type','receipt','switch','frame','cards','marquee','split','index','windows','signal','manifesto']
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font)}a{color:inherit}header{display:flex;align-items:center;justify-content:space-between;padding:22px 5vw;border-bottom:1px solid currentColor;font-family:Arial,sans-serif;font-size:13px;font-weight:700}header .brand{font-size:20px;letter-spacing:-1px}.mark{display:inline-grid;place-items:center;width:25px;height:25px;background:var(--ink);color:var(--bg);margin-right:8px}nav{display:flex;gap:25px}main{min-height:calc(100vh - 69px);padding:5vw;display:grid;gap:4vw}.eyebrow,.label,.tiny{font:700 11px/1.4 monospace;text-transform:uppercase;letter-spacing:.13em}.eyebrow{display:flex;gap:15px;align-items:center}.eyebrow:before{content:'';width:34px;height:2px;background:var(--accent)}h1{font-size:clamp(48px,7.4vw,122px);line-height:.9;letter-spacing:-.065em;margin:25px 0;max-width:1100px}h1 em{font-style:normal;color:var(--accent)}.desc{font:400 clamp(16px,1.5vw,21px)/1.5 Arial,sans-serif;max-width:540px}.action{margin-top:28px;max-width:600px}.command{display:flex;border:1px solid currentColor;padding:8px;background:var(--bg);gap:10px;align-items:center}.command code{flex:1;padding:12px;font:13px monospace;overflow-wrap:anywhere}.command button{border:0;background:var(--ink);color:var(--bg);padding:14px 18px;cursor:pointer;font-weight:bold}.stores{display:flex;gap:9px;margin-top:12px;flex-wrap:wrap}.stores button{background:transparent;border:1px solid currentColor;color:inherit;opacity:.5;padding:10px 13px;font:11px Arial;cursor:not-allowed}.note{font:12px/1.5 Arial,sans-serif;max-width:590px;opacity:.8}.stage{position:relative;min-height:300px;border:1px solid currentColor;padding:22px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden}.stage-head{display:flex;justify-content:space-between;border-bottom:1px solid currentColor;padding-bottom:12px}.platforms{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:auto 0}.platform{border:1px solid currentColor;padding:20px 10px;min-height:74px;font:700 13px Arial,sans-serif;display:flex;flex-direction:column;gap:8px}.platform b{font:11px monospace;color:var(--accent)}.stage-foot{border-top:1px solid currentColor;padding-top:12px}.v0 main{grid-template-columns:1.45fr .7fr;align-items:end}.v0 .copy{grid-column:1}.v1 main{grid-template-columns:1fr 1fr;align-items:center}.v2 main{grid-template-columns:1fr 1.15fr;align-items:center}.v2 .stage{order:-1;min-height:520px}.v3 main{grid-template-columns:1fr 1fr;align-items:center}.v3 .copy{display:contents}.v3 .eyebrow,.v3 h1,.v3 .desc{grid-column:1/-1}.v3 h1{max-width:1100px;margin:0}.v3 .action{grid-column:1;align-self:start}.v3 .stage{grid-column:2;grid-row:4/7}.v4 main{grid-template-columns:180px 1fr 1fr;align-items:center}.v4 .copy{display:contents}.v4 .eyebrow{grid-column:1;grid-row:1/4;writing-mode:vertical-rl;align-self:stretch}.v4 h1,.v4 .desc,.v4 .action,.v4 .note{grid-column:2}.v4 .stage{grid-column:3;grid-row:1/6}.v4 h1{font-size:clamp(44px,5.2vw,90px)}.sheet .stage{border-width:4px}.desk .stage{box-shadow:14px 14px 0 var(--accent);transform:rotate(2deg)}.terminal .stage{background:#060a08;border:1px solid #7c9a7a}.terminal .platform{border:0;border-bottom:1px solid #455b47}.prism .platform{background:var(--accent);color:white;opacity:.8;transform:skew(-8deg)}.blueprint .stage{background-image:linear-gradient(#ffffff19 1px,transparent 1px),linear-gradient(90deg,#ffffff19 1px,transparent 1px);background-size:22px 22px}.manual .platform{border:0;border-top:2px solid}.manual .platform b{font-size:22px}.conveyor .platforms{display:flex;overflow:hidden}.conveyor .platform{min-width:120px;border-radius:100px;text-align:center}.orbit .platforms{display:flex;flex-wrap:wrap;justify-content:center}.orbit .platform{border-radius:50%;width:100px;height:100px;align-items:center;justify-content:center}.devices .platform{border-width:5px;border-radius:13px;min-height:130px}.type .platforms{display:block}.type .platform{font-size:38px;line-height:.8;border:0;padding:6px;display:inline-flex;letter-spacing:-.08em}.receipt .stage{border:0;border-left:2px dashed;border-right:2px dashed;background:#fffdf2;color:#282820}.receipt .platform{border:0;border-bottom:1px dashed}.switch .stage{background:#343c38;color:white;border:8px solid #222}.switch .platform{background:#171e1b;border-radius:8px;box-shadow:inset 0 3px 0 #667}.frame .stage{border:3px solid;outline:1px solid;outline-offset:8px}.frame .platform{border-style:dashed}.cards .platform{box-shadow:5px 5px 0 var(--accent);transform:rotate(-2deg)}.marquee .platform{background:var(--ink);color:var(--bg);border:0;transform:rotate(-3deg);font-size:19px}.split .stage{background:var(--ink);color:var(--bg)}.index .platform{border:0;border-top:1px solid;font-family:Georgia,serif;font-size:21px}.windows .platform{background:#293340;border:1px solid #677480}.windows .stage-head:before{content:'● ● ●';color:var(--accent)}.signal .stage{border-radius:50%;aspect-ratio:1}.signal .platform{border-radius:50%;text-align:center;justify-content:center}.manifesto .platform{border:0;border-bottom:3px solid;font-family:Georgia,serif;font-style:italic;font-size:20px}@media(max-width:700px){header{padding:17px 5vw}nav a:nth-child(-n+2){display:none}main,.v0 main,.v1 main,.v2 main,.v3 main,.v4 main{display:flex;flex-direction:column;align-items:stretch;padding:9vw 5vw;gap:28px}.v2 .stage{order:0;min-height:300px}.v4 .eyebrow{writing-mode:initial}.stage{min-height:280px}h1,.v4 h1{font-size:clamp(45px,11vw,72px)}.command{align-items:stretch}.command code{font-size:11px}.platform{padding:12px 8px;min-height:60px}.signal .stage{border-radius:20px;aspect-ratio:auto}}'''
items=[]
for fi,(name,concept,why,risk,bg,ink,accent,font) in enumerate(families):
 for vi,(variant,vrationale) in enumerate(variants):
  n=fi*5+vi+1; shape=shapes[fi]; title=f'{name} / {variant}'
  platforms=['Web','iOS','Android','macOS','Windows','Linux']
  cards=''.join(f'<div class="platform"><b>{i+1:02}</b><span>{x}</span></div>' for i,x in enumerate(platforms))
  doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} — Disposabl concept</title><style>:root{{--bg:{bg};--ink:{ink};--accent:{accent};--font:{font}}}{css}</style></head><body class="v{vi} {shape}"><header><div class="brand"><span class="mark">d.</span>disposabl</div><nav aria-label="Concept navigation"><a href="#platforms">Platforms</a><a href="#pricing">Pricing</a><a href="https://github.com/disposabl-dev/create-disposabl-app">GitHub ↗</a></nav></header><main><div class="copy"><div class="eyebrow">Open source · build on your computer</div><h1>{headlines[vi]}</h1><p class="desc">Build apps with your coding agent, on your computer, with code you own. Start with a foundation built for the platforms you choose.</p><div class="action"><div class="label">Start building</div><div class="command"><code id="cmd">bunx create-disposabl-app@latest</code><button type="button" onclick="navigator.clipboard?.writeText(document.getElementById('cmd').textContent).then(()=>this.textContent='Copied')">Copy command</button></div><div class="stores"><button disabled>App Store · Coming soon</button><button disabled>Google Play · Coming soon</button></div></div><p class="note" id="pricing">Disposabl is free and open source. Your AI provider, hosting, and other services may charge separately.</p></div><section class="stage" id="platforms" aria-label="Illustrative platform graphic"><div class="stage-head"><span class="label">One foundation / many platforms</span><span class="tiny">{n:03}</span></div><div class="platforms">{cards}</div><div class="stage-foot tiny">Your idea → your code → your platforms</div></section></main></body></html>'''
  (v/f'{n:03}.html').write_text(doc)
  items.append({'id':f'{n:03}','family':name,'variant':variant,'visual_concept':concept,'composition':vrationale,'rationale':why,'tradeoff':risk,'file':f'versions/{n:03}.html','rubric':{'clarity':'subjective','distinctiveness':'subjective','credibility':'subjective','responsive_feasibility':'subjective','accessibility':'subjective'}})
(p/'manifest.json').write_text(json.dumps({'note':'Concept directions and rubric are subjective design judgments; no conversion, user testing, or empirical metrics are claimed.','versions':items},indent=2))
options=''.join(f'<option value="{x["file"]}">{x["id"]} — {x["family"]} / {x["variant"]}</option>' for x in items)
(p/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Disposabl design lab</title><style>body{font:15px system-ui;margin:0;background:#e9e8e4;color:#151515}header{padding:18px 24px;background:#171717;color:white;display:flex;align-items:center;gap:18px;flex-wrap:wrap}h1{font-size:18px;margin:0}label{display:flex;gap:8px;align-items:center}select,button{font:inherit;padding:8px}main{padding:24px;overflow:auto}.frame{background:white;margin:auto;transition:width .2s;max-width:100%;box-shadow:0 5px 30px #0002}.frame.mobile{width:390px}.frame.desktop{width:1440px}iframe{border:0;width:100%;height:900px;display:block}.caption{padding:0 24px}a{color:inherit}</style></head><body><header><h1>Disposabl / Design lab</h1><label>Concept <select id="pick">'''+options+'''</select></label><button id="prev" type="button">Previous</button><button id="next" type="button">Next</button><label>Viewport <select id="size"><option value="desktop">Desktop</option><option value="mobile">Mobile · 390px</option></select></label><a href="review.md">Review notes</a></header><p class="caption">100 exploratory concepts. All previews are illustrative; select a version and viewport to compare.</p><main><div class="frame desktop" id="frame"><iframe id="preview" title="Selected landing page concept" src="versions/001.html"></iframe></div></main><script>const pick=document.querySelector('#pick'),frame=document.querySelector('#frame'),preview=document.querySelector('#preview');function show(){preview.src=pick.value}pick.addEventListener('change',show);document.querySelector('#size').addEventListener('change',e=>frame.className='frame '+e.target.value);document.querySelector('#prev').onclick=()=>{pick.selectedIndex=Math.max(0,pick.selectedIndex-1);show()};document.querySelector('#next').onclick=()=>{pick.selectedIndex=Math.min(pick.options.length-1,pick.selectedIndex+1);show()};</script></body></html>''')
(p/'review.md').write_text('''# Subjective design review\n\nThese are design hypotheses, evaluated from the written compositions and generated HTML, not observed user tests. No conversion, preference, or performance metrics are claimed. All previews are illustrative and should be checked visually in target browsers before production. The five compositions change ordering and hierarchy; the family-specific CSS changes the platform graphic, typography, and visual grammar.\n\nCriteria: clarity of promise and action, distinctiveness, credibility, responsive feasibility, and accessibility.\n\n1. **001 — Launch Sheet / Front Page (recommended):** Strong typographic hierarchy, command beside a clear platform proof, and an honest cost note. The most balanced candidate for production. Risk: the long ownership headline needs careful wrapping on small screens.\n2. **002 — Launch Sheet / Split Desk:** A balanced two-column composition keeps the platform proof visible. Risk: less room for long copy.\n3. **004 — Launch Sheet / Command Stage:** Makes the next action a primary object. Risk: the headline-to-action separation needs visual verification.\n4. **056 — Switchboard / Front Page:** A tactile platform panel gives the concept a recognizable identity. Risk: must not suggest that the depicted platforms are interactive switches.\n5. **096 — Manifesto / Front Page:** The ownership statement has conviction and legibility. Risk: platform evidence competes with the claim.\n6. **016 — Prism / Front Page:** Layered forms make the multi-platform idea visually distinctive. Risk: skewed cards could impair scanability.\n7. **021 — Blueprint / Front Page:** The grid supports a credible technical foundation story. Risk: the engineering aesthetic may narrow appeal.\n8. **076 — Split Reality / Front Page:** Input and platform outcome are easy to relate. Risk: avoid implying the illustrative panel is a generated result.\n9. **051 — Receipt / Front Page:** A cost ledger reinforces transparency. Risk: the visual is more utilitarian than aspirational.\n10. **041 — App Gallery / Front Page:** Device silhouettes help explain platform reach. Risk: they are schematic rather than genuine app examples.\n\n## Production copy guidance\n\nClaude Code helps you write software. Disposabl gives your coding agent a ready-to-run foundation for apps across platforms, with your code on your computer. Claude Code can also build apps; the distinction here is the provided foundation and workflow.\n\nThe command is illustrative and should be verified against the actual onboarding before shipping. Store buttons are intentionally disabled. AI providers, hosting, and other external services may charge separately.\n''')
print(f'Generated {len(items)} candidates, {len(set(x["file"] for x in items))} distinct paths, {len(set((x["family"],x["variant"]) for x in items))} unique family/variant pairs.')
